var QPROMPTS=[
["q01","A1","person","Ask the patient's name.","Wie heißen Sie?",/^wie heissen sie$|^wie ist ihr name$/],
["q02","A1","person","Ask where the patient lives.","Wo wohnen Sie?",/^wo wohnen sie$/],
["q03","A1","person","Ask when the patient was born.","Wann sind Sie geboren?",/^wann sind sie geboren$/],
["q04","A1","person","Ask how old the patient is.","Wie alt sind Sie?",/^wie alt sind sie$/],
["q05","A1","person","Ask where the patient comes from.","Woher kommen Sie?",/^woher kommen sie$/],
["q06","A1","person","Ask for the phone number.","Wie ist Ihre Telefonnummer?",/^wie ist ihre (telefonnummer|handynummer|nummer)$/],
["q07","A1","person","Ask what the patient's job is.","Was sind Sie von Beruf?",/^was sind sie von beruf$|^was machen sie beruflich$|^was arbeiten sie$/],
["q08","A1","person","Ask whether the patient is married.","Sind Sie verheiratet?",/^sind sie verheiratet$/],
["q09","A1","befinden","Ask how the patient is.","Wie geht es Ihnen?",/^wie geht es ihnen( heute)?$/],
["q10","A1","befinden","Ask where it hurts.","Wo tut es weh?",/^wo tut es (ihnen )?(genau )?weh$|^wo haben sie schmerzen$/],
["q11","A1","befinden","Ask since when the patient has had the pain.","Seit wann haben Sie die Schmerzen?",/^seit wann haben sie (die |diese |das |)?(schmerzen|beschwerden)$|^seit wann tut es weh$/],
["q12","A1","befinden","Ask whether the patient has a fever.","Haben Sie Fieber?",/^haben sie fieber$/],
["q13","A1","befinden","Ask whether the patient feels sick (nausea).","Ist Ihnen übel?",/^ist ihnen (uebel|schlecht)$/],
["q14","A1","befinden","Ask whether the patient takes medication.","Nehmen Sie Medikamente?",/^nehmen sie (regelmaessig )?medikamente( ein)?$/],
["q15","A1","befinden","Ask whether the patient smokes.","Rauchen Sie?",/^rauchen sie$/],
["q16","A1","befinden","Ask whether the patient has allergies.","Haben Sie Allergien?",/^haben sie (eine allergie|allergien)$|^sind sie (gegen etwas )?allergisch$/],
["q17","A1","organisation","Ask whether the patient has an insurance card.","Haben Sie Ihre Versichertenkarte?",/^haben sie (ihre|eine) (versichertenkarte|gesundheitskarte|krankenkassenkarte)( dabei)?$/],
["q18","A1","organisation","Ask who the family doctor is.","Wer ist Ihr Hausarzt?",/^wer ist ihr hausarzt$|^wer ist ihre hausaerztin$/],
["q19","A1","organisation","Ask whether the patient can come tomorrow.","Können Sie morgen kommen?",/^koennen sie morgen (wieder)?kommen$/],
["q20","A1","organisation","Ask what time it is.","Wie spät ist es?",/^wie spaet ist es$|^wie viel uhr ist es$/],
["q21","A2","schmerz","Pain history 1 of 6: where exactly?","Wo genau tut es weh?",/^wo (genau )?(tut es (ihnen )?(genau )?weh|haben sie (die )?schmerzen)$|^koennen sie mir zeigen wo es wehtut$/],
["q22","A2","schmerz","Pain history 2 of 6: since when?","Seit wann haben Sie die Schmerzen?",/^seit wann (haben sie (die |diese )?(schmerzen|beschwerden)|tut es weh|bestehen die (schmerzen|beschwerden))$/],
["q23","A2","schmerz","Pain history 3 of 6: what is the pain like?","Wie fühlt sich der Schmerz an?",/^wie fuehlt sich der schmerz an$|^wie (ist|sind) (der schmerz|die schmerzen)( stechend| drueckend| brennend| oder)*$|^koennen sie (den schmerz|die schmerzen) beschreiben$/],
["q24","A2","schmerz","Pain history 4 of 6: how strong, on a scale from 0 to 10?","Wie stark sind die Schmerzen auf einer Skala von 0 bis 10?",/^wie stark (sind die schmerzen|ist der schmerz) (auf einer skala )?von (0|null) bis (10|zehn)$|^wie stark (sind die schmerzen|ist der schmerz) auf einer skala von (0|null) bis (10|zehn)$/],
["q25","A2","schmerz","Pain history 5 of 6: does it radiate, and where to?","Strahlt der Schmerz aus? Wohin?",/^strahl(t|en) (der schmerz|die schmerzen) (irgendwohin )?aus( wohin| und wohin)?$|^wohin strahl(t|en) (der schmerz|die schmerzen) aus$/],
["q26","A2","schmerz","Pain history 6 of 6: what makes it better or worse?","Was macht den Schmerz besser oder schlechter?",/^was macht (den schmerz|die schmerzen|es) (besser oder (schlechter|schlimmer)|(schlechter|schlimmer) oder besser)$|^wodurch (wird|werden) (der schmerz|die schmerzen) (besser|staerker|schlimmer|gelindert|ausgeloest)( oder (besser|staerker|schlimmer))?$/],
["q27","A2","vorerkrankungen","Ask about known illnesses.","Haben Sie Vorerkrankungen?",/^haben sie (irgendwelche )?(vorerkrankungen|chronische(n)? (krankheiten|erkrankungen))$|^sind bei ihnen (krankheiten|erkrankungen|vorerkrankungen) bekannt$/],
["q28","A2","vorerkrankungen","Ask whether the patient has had an operation.","Sind Sie schon einmal operiert worden?",/^sind sie schon (ein)?mal operiert worden$|^wurden sie schon (ein)?mal operiert$|^hatten sie schon (ein)?mal eine operation$/],
["q29","A2","medikamente","Ask which medication the patient takes regularly.","Welche Medikamente nehmen Sie regelmäßig ein?",/^welche medikamente nehmen sie( regelmaessig)?( ein)?$/],
["q30","A2","medikamente","Ask whether the patient takes blood thinners.","Nehmen Sie Blutverdünner?",/^nehmen sie (blutverduenner|blutverduennende medikamente|ein blutverduennendes medikament)( ein)?$/],
["q31","A2","allergien","Ask whether the patient is allergic to any medication.","Sind Sie gegen Medikamente allergisch?",/^sind sie gegen (ein |bestimmte |irgendwelche )?(medikament|medikamente) allergisch$|^haben sie (eine allergie|allergien) gegen (ein |bestimmte )?(medikament|medikamente)$/],
["q32","A2","allergien","Ask what happens when the patient takes penicillin.","Was passiert, wenn Sie Penicillin nehmen?",/^was passiert wenn sie penicillin (ein)?nehmen$|^wie reagieren sie auf penicillin$/],
["q33","A2","untersuchung","Tell the patient to take off his shirt.","Ziehen Sie bitte das Hemd aus.",/^(bitte )?ziehen sie (bitte )?(das|ihr) (hemd|oberteil|t shirt) aus$|^machen sie (bitte )?den oberkoerper frei$/],
["q34","A2","untersuchung","Tell the patient to lie down.","Legen Sie sich bitte hin.",/^(bitte )?legen sie sich (bitte )?(hin|auf die liege|auf den ruecken)$/],
["q35","A2","untersuchung","Tell the patient to breathe in deeply.","Atmen Sie bitte tief ein.",/^(bitte )?atmen sie (bitte )?tief ein( und aus)?$/],
["q36","A2","untersuchung","Tell the patient to open his mouth.","Machen Sie bitte den Mund auf.",/^(bitte )?(machen sie (bitte )?den mund( weit)? auf|oeffnen sie (bitte )?den mund)$/],
["q37","A2","untersuchung","Tell the patient to say when it hurts.","Sagen Sie bitte, wenn es wehtut.",/^(bitte )?sagen sie (mir )?(bitte )?(bescheid )?wenn es (ihnen )?(weh ?tut|wehtut|schmerzt)$/],
["q38","A2","untersuchung","Tell the patient to hold his breath.","Halten Sie bitte die Luft an.",/^(bitte )?halten sie (bitte )?die luft an$/]
].map(([id,lv,rub,cue,model,re])=>({id,lv,rub,cue,model,re}));
var CARDS_ASSESS=[
{de:"Noch einmal, bitte.",pl:"",en:"Once more, please.",type:"phrase",ex:"Noch einmal, bitte. Ich habe den Namen nicht verstanden.",exEn:"Once more, please. I did not catch the name.",level:"A1",theme:"redemittel-basis",info:"",syn:"Wie bitte?",src:"assess"},
{de:"Bitte sprechen Sie langsamer.",pl:"",en:"Please speak more slowly.",type:"phrase",ex:"Bitte sprechen Sie langsamer. Ich lerne noch Deutsch.",exEn:"Please speak more slowly. I am still learning German.",level:"A1",theme:"redemittel-basis",info:"",syn:"",src:"assess"},
{de:"Ich verstehe das nicht.",pl:"",en:"I do not understand that.",type:"phrase",ex:"Entschuldigung, ich verstehe das nicht. Was bedeutet „nüchtern“?",exEn:"Sorry, I do not understand that. What does 'nüchtern' mean?",level:"A1",theme:"redemittel-basis",info:"",syn:"",src:"assess"}];
var TASKS_ASSESS=[
{t:"Weitergabe an die Pflege",k:"klinik",task:"Du hast mit Frau Kaya (58) gesprochen. Schreib der Pflegekraft <b>vier kurze Sätze</b>: Wer? Was hat sie? Seit wann? Was soll jetzt passieren?",ctx:"Notaufnahme, Zettel für die Pflege",reg:"kurz, sachlich",check:["Name und Alter","Beschwerde","seit wann","nächster Schritt"],model:"Frau Kaya ist 58 Jahre alt. Sie hat starke Bauchschmerzen. Die Schmerzen hat sie seit heute Morgen. Bitte nehmen Sie Blut ab und messen Sie den Blutdruck."},
{t:"Mein Dienst",k:"klinik",task:"Beschreib einem neuen Kollegen deinen Dienst (<b>5 Sätze</b>): Wann beginnt er? Was machst du zuerst? Was machst du oft? Wann ist er zu Ende?",ctx:"Pause mit einem neuen Kollegen",reg:"du-Form, einfach",check:["Beginn mit Uhrzeit","zuerst … dann","eine häufige Aufgabe","Ende"],model:"Mein Dienst beginnt um sieben Uhr. Zuerst gibt es die Übergabe. Dann sehe ich die neuen Patienten. Ich frage sie nach ihren Beschwerden und untersuche sie. Um halb vier ist der Dienst zu Ende."},
{t:"Mein Nachtdienst",k:"klinik",task:"Erzähl von einem Nachtdienst (<b>6–8 Sätze, Präteritum und Perfekt</b>): Was passierte? Was hast du gemacht? Wie ging es aus?",ctx:"Kantine, am Morgen danach",reg:"erzählend, Kollegen",check:["Zeit und Ort","ein Ereignis im Präteritum","was du getan hast","wie es ausging","mindestens ein Nebensatz"],model:"Letzte Nacht hatte ich Dienst in der Notaufnahme. Gegen zwei Uhr kam ein Mann mit starken Brustschmerzen. Er war blass und schwitzte. Ich habe sofort ein EKG geschrieben und den Oberarzt angerufen. Weil das EKG auffällig war, haben wir den Patienten ins Herzkatheterlabor gebracht. Am Morgen ging es ihm schon besser. Danach war ich sehr müde, aber zufrieden."},
{t:"Meinung: Vor- und Nachteile",k:"alltag",task:"Sollen Ärztinnen und Ärzte 24-Stunden-Dienste machen? Schreib deine Meinung (<b>6–8 Sätze</b>): ein Vorteil, ein Nachteil, deine Meinung mit Grund.",ctx:"Diskussion im Team",reg:"sachlich",check:["ein Vorteil","ein Nachteil","eigene Meinung","Begründung mit weil oder denn"],model:"Über 24-Stunden-Dienste gibt es verschiedene Meinungen. Ein Vorteil ist, dass der Patient lange denselben Arzt hat. Außerdem hat man danach mehr freie Tage. Ein Nachteil ist aber, dass man nach zwanzig Stunden sehr müde ist. Dann macht man leichter Fehler. Ich bin gegen so lange Dienste, weil die Sicherheit der Patienten wichtiger ist. Meiner Meinung nach sind zwölf Stunden genug."},
{t:"Konsil am Telefon",k:"klinik",task:"Du rufst die Chirurgin an. Schreib auf, was du sagst (<b>5–6 Sätze</b>): Wer bist du? Welcher Patient? Was hat er? Was möchtest du? Wie dringend ist es?",ctx:"Telefonat mit der Chirurgie",reg:"Sie-Form, knapp, Fachsprache erlaubt",check:["Name und Abteilung","Patient mit Alter","Befund","klare Bitte","Dringlichkeit"],model:"Guten Tag, hier spricht Dr. Berger aus der Notaufnahme. Ich habe einen 34-jährigen Patienten mit Schmerzen im rechten Unterbauch seit gestern Abend. Er hat Fieber, und der Bauch ist rechts unten druckschmerzhaft. Die Entzündungswerte sind erhöht. Ich bitte Sie um ein chirurgisches Konsil. Könnten Sie in der nächsten halben Stunde kommen?"},
{t:"Kurzvorstellung",k:"klinik",task:"Stell dem Oberarzt einen Patienten in <b>sechs Sätzen</b> vor: Name und Alter, Leitsymptom, Vorerkrankungen, Befund, Verdacht, Plan.",ctx:"Visite, 60 Sekunden",reg:"Sie-Form, Fachsprache",check:["Name und Alter","Leitsymptom mit Dauer","Vorerkrankungen","Befund","Verdachtsdiagnose","Plan"],model:"Das ist Herr Weber, 67 Jahre alt. Er kommt wegen Luftnot, die seit drei Tagen zunimmt. An Vorerkrankungen sind ein Bluthochdruck und eine Herzschwäche bekannt. Bei der Untersuchung höre ich Rasselgeräusche über beiden Lungen, und die Beine sind geschwollen. Ich vermute eine dekompensierte Herzinsuffizienz. Ich würde ein Röntgenbild der Lunge machen und ihm ein Diuretikum geben."},
{t:"Faust in einfachem Deutsch",k:"alltag",task:"Lies Fausts ersten Monolog („Habe nun, ach! Philosophie …“). Erklär in <b>fünf einfachen Sätzen</b>: Was hat Faust gelernt? Wie fühlt er sich? Warum?",ctx:"Fausts Studierzimmer",reg:"einfaches Deutsch, eigene Worte",check:["was Faust studiert hat","wie er sich fühlt","der Grund","ein eigener Satz dazu"],model:"Faust hat sehr viel studiert: Philosophie, Recht, Medizin und Theologie. Trotzdem ist er nicht zufrieden. Er glaubt, dass er am Ende nichts Wichtiges weiß. Deshalb ist er traurig und wütend. Ich kenne das Gefühl: Je mehr man lernt, desto mehr Fragen hat man."},
{t:"Zusammenfassung für den Patienten",k:"klinik",task:"Lies die Patienteninformation in der Bibliothek. Erklär dem Patienten das Wichtigste in <b>drei bis vier einfachen Sätzen</b> – ohne Fachwörter.",ctx:"Am Bett, vor der Untersuchung",reg:"Sie-Form, Laiensprache",check:["was gemacht wird","was der Patient tun soll","worauf er achten muss","kein Fachwort ohne Erklärung"],model:"Wir machen morgen früh eine Untersuchung von Ihrem Magen. Bitte essen Sie ab heute Abend nichts mehr; Wasser dürfen Sie trinken. Nach der Untersuchung sind Sie etwas müde und dürfen nicht Auto fahren. Wenn Sie danach starke Schmerzen haben, sagen Sie uns bitte sofort Bescheid."},
{t:"Drei-Satz-Zusammenfassung",k:"klinik",task:"Lies die Pressemitteilung in der Bibliothek. Fass sie für die Frühbesprechung in <b>genau drei Sätzen</b> zusammen: Thema, wichtigstes Ergebnis, Bedeutung für uns.",ctx:"Frühbesprechung",reg:"sachlich, Kollegen",check:["Thema","wichtigstes Ergebnis","Bedeutung für die Abteilung","genau drei Sätze"],model:"In der Pressemitteilung geht es um die neue Regelung für die Notfallversorgung in der Stadt. Wichtig ist vor allem, dass leichte Fälle künftig zuerst in die Bereitschaftspraxis geschickt werden sollen. Für uns bedeutet das, dass wir an der Anmeldung genauer einschätzen müssen, wer wirklich in die Notaufnahme gehört."},
{t:"Befund in Laiensprache",k:"klinik",task:"Befund: „Im CT zeigt sich eine segmentale Lungenarterienembolie rechts; Beginn einer therapeutischen Antikoagulation.“ Erklär das dem Patienten in <b>vier bis fünf einfachen Sätzen</b>.",ctx:"Am Bett, nach dem CT",reg:"Sie-Form, Laiensprache, ruhig",check:["was gefunden wurde, in einfachen Worten","was das bedeutet","was jetzt gemacht wird","was der Patient melden soll","kein Fachwort ohne Erklärung"],model:"Wir haben in der Untersuchung ein Blutgerinnsel in einem Gefäß Ihrer rechten Lunge gefunden. Das erklärt, warum Sie so schlecht Luft bekommen. Sie bekommen jetzt ein Medikament, das das Blut dünner macht, damit sich das Gerinnsel auflöst und kein neues entsteht. Sie bleiben dafür einige Tage bei uns im Krankenhaus. Bitte sagen Sie sofort Bescheid, wenn die Luftnot stärker wird oder wenn Sie Blut im Speichel bemerken."}];
var TASK_LV_ASSESS={"Weitergabe an die Pflege":1,"Mein Dienst":1,"Mein Nachtdienst":2,"Meinung: Vor- und Nachteile":2,"Konsil am Telefon":2,"Kurzvorstellung":2,"Faust in einfachem Deutsch":2,"Zusammenfassung für den Patienten":2,"Drei-Satz-Zusammenfassung":3,"Befund in Laiensprache":4};
